def chart(color='#4779e8'):
 return f'<svg viewBox="0 0 320 105"><path d="M0 85H320 M0 50H320 M0 15H320" stroke="#e9edf5"/><path d="M0 78L35 62 65 70 100 32 130 50 170 20 210 36 250 15 290 30 320 8" fill="none" stroke="{color}" stroke-width="4"/><path d="M0 78L35 62 65 70 100 32 130 50 170 20 210 36 250 15 290 30 320 8V105H0Z" fill="{color}" opacity=".08"/></svg>'
def table(headers,rows):
 return '<table><thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def window(title,body,tabs='Visão geral · Relatórios · Configurações'):
 return '<div class="win"><header><i></i><i></i><i></i><span>DEMO / '+title+'</span></header><div class="nav"><b>▦</b><b>◉</b><b>▤</b><b>⚙</b></div><main><h2>'+title+'</h2><p class="tabs">'+tabs+'</p>'+body+'</main></div>'
