 ('EVENTOS E JORNADA',window('Jornada','<div class="funnel"><div>Visita · exemplo</div><div>Produto · exemplo</div><div>Carrinho · exemplo</div><div>Pedido · exemplo</div></div><p class="muted">Eventos demonstrativos · sem dados reais</p>')),
