css='''*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#263249}.atlas{width:1920px;height:1280px;display:grid;grid-template-columns:repeat(4,480px);grid-template-rows:repeat(3,1fr)}.panel{position:relative;overflow:hidden;padding:58px 30px 30px;background:linear-gradient(140deg,#e1eafd,#b8cef4)}.panel:nth-child(3n){background:linear-gradient(145deg,#d7f0e5,#a3d6cb)}.panel:nth-child(4n){background:linear-gradient(145deg,#eedff4,#c8bde8)}.panel:before{content:'';position:absolute;width:240px;height:240px;border:30px solid #ffffff25;border-radius:50%;top:-100px;right:-70px}.label{position:absolute;top:24px;left:30px;font-size:12px;letter-spacing:1.8px;font-weight:800}.win{position:relative;height:320px;background:#fff;border-radius:10px;box-shadow:0 22px 25px #23355735;overflow:hidden;border:1px solid #ffffffcc}.panel:nth-child(2n) .win{transform:perspective(1100px) rotateY(-7deg) rotateX(3deg)}header{height:30px;border-bottom:1px solid #edf0f5;background:#f6f8fc;display:flex;gap:5px;align-items:center;padding:9px}header i{background:#bdc9d9;width:6px;height:6px;border-radius:50%}header span{font-size:9px;color:#63768c;margin-left:8px}.nav{position:absolute;width:34px;top:30px;bottom:0;background:#f5f7fb;display:flex;flex-direction:column;align-items:center;gap:23px;padding-top:18px;color:#7d8aa3;font-size:14px}main{margin-left:34px;padding:16px 13px}h2{font-size:16px;margin:0 0 10px}.tabs{font-size:8px;color:#7a879c;border-bottom:1px solid #e8edf4;padding-bottom:10px;margin:0 0 12px}table{width:100%;border-collapse:collapse;font-size:8px;text-align:left}th{background:#f5f7fb;color:#6e7d94}td,th{padding:10px 5px;border-bottom:1px solid #eef1f5}.toolbar{display:flex;justify-content:space-between;align-items:center;font-size:9px;margin:12px 0}button{border:0;background:#376fdf;color:white;border-radius:4px;padding:7px 10px;font-size:9px}.kpis{display:flex;gap:7px}.kpis>div{flex:1;background:#f6f8fc;padding:8px;border-radius:5px}.kpis small{font-size:8px}.kpis strong{display:block;font-size:20px;margin:5px 0}.kpis em{font-size:7px;font-style:normal;color:#8290a2}svg{width:100%;height:90px}.funnel>div{background:#dce9fc;margin:6px auto;text-align:center;padding:9px;font-size:10px}.funnel>div:nth-child(2){width:80%;background:#b9d2f8}.funnel>div:nth-child(3){width:60%;background:#82acee}.funnel>div:nth-child(4){width:40%;background:#4b82d5;color:white}.muted{font-size:8px;color:#7a879c}.products{display:flex;gap:8px;margin-bottom:10px}.products>div{background:#f0f1f6;flex:1;text-align:center;font-size:36px;color:#998dbe;padding:8px}.products small{display:block;font-size:8px;color:#68748a}.bubble{font-size:10px;padding:9px;background:#edf0f5;border-radius:8px;margin:8px 0;max-width:90%}.right{margin-left:30px;background:#dbf1e8}.kanban{display:flex;gap:8px}.kanban section{flex:1;background:#f3f6fb;padding:7px;font-size:9px;height:175px}.kanban article{background:white;border-radius:5px;padding:12px 5px;margin:10px 0;box-shadow:0 2px 4px #17334a11}.kanban small{font-size:7px;color:#8793a5}.step{font-size:9px;margin:10px 0}.select{border:1px solid #dfe6ef;padding:9px;font-size:10px;border-radius:4px}.select b{float:right}.large{margin-top:12px}.tip{font-size:9px;color:#806420;background:#fff3cd;padding:8px;margin-top:10px;border-radius:4px}.nodes{display:flex;align-items:center;justify-content:center;gap:9px;margin:20px 0;font-size:12px}.nodes div{background:#e9eefc;border:1px solid #c9d7f4;padding:12px;text-align:center;border-radius:8px;font-size:11px}.bars{display:flex;height:45px;align-items:flex-end;gap:18px}.bars i{width:30px;background:#91cbbb;border-radius:3px}.split,.inbox{display:flex;gap:9px;font-size:10px}.split section{flex:1;background:#f4f6fa;padding:12px}.split p{background:#e3eaf5;padding:9px}.inbox section{flex:1}.inbox section:first-child{background:#f6f7fa;padding:9px;flex:.6}.inbox p{font-size:9px;margin:20px 0}.zoom{position:absolute;bottom:23px;right:15px;width:260px;background:white;border:2px solid #4e84e4;box-shadow:0 10px 18px #243e6e33;padding:14px;border-radius:8px}.zoom small{font-size:9px;color:#6e7f9a}.zoom div{font-size:12px;margin:12px 0}.zoom button{float:right}.demo{position:absolute;bottom:10px;left:30px;font-size:8px;font-weight:700;letter-spacing:.7px;color:#3e577c}'''
html='<html lang="pt-BR"><meta charset="utf-8"><style>'+css+'</style><div class="atlas">'+''.join('<section class="panel"><div class="label">'+title+'</div>'+body+'<div class="demo">UI DEMONSTRATIVA · NÃO É CAPTURA OFICIAL</div></section>' for title,body in panels)+'</div></html>'
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':1920,'height':1280},device_scale_factor=1)
 page.set_content(html);page.screenshot(path=str(ROOT/('dist/assets/software-extra.png' if extra else 'dist/assets/software.png')));browser.close()
