out=ROOT/('dist/assets/software-extra.webp' if extra else 'dist/assets/software.webp');Image.open(ROOT/('dist/assets/software-extra.png' if extra else 'dist/assets/software.png')).save(out,quality=95);(ROOT/('dist/assets/software-extra.png' if extra else 'dist/assets/software.png')).unlink()
manifest=ROOT/'records/assets.json';d=json.loads(manifest.read_text());family='software-extra' if extra else 'software';d['assets']=[a for a in d['assets'] if a['family']!=family];d['assets'].append(dict(family=family,file=str(out.relative_to(ROOT)),width=1920,height=1280,cells=8 if extra else 12,source='Interfaces demonstrativas originais construídas em HTML/CSS/SVG; ícones geométricos e dados ilustrativos; não são capturas de plataformas',processing='Render Chromium; conversão para WebP',sha256=hashlib.sha256(out.read_bytes()).hexdigest()));manifest.write_text(json.dumps(d,ensure_ascii=False,indent=2));print('12 UI demonstration images rendered')
